using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad] public static class CasinoPavingLayout { static CasinoPavingLayout(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CasinoPavingLayout.request"))return;File.Delete("CasinoPavingLayout.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CasinoPavingLayout.txt",e.ToString());Debug.LogException(e);}}static void Run(){var sc=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var host=sc.GetRootGameObjects().Single(g=>g.name=="Track Roads");var map=host.GetComponent<CityGroundTextureLayout>();var p=map.plots.Single(t=>t.renderer.name=="polySurface285");string prefab=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(host),bk="FinalEnvironmentRoadBackup/BeforeCasinoRearPaving/";foreach(var f in new[]{sc.path,prefab})if(!File.Exists(bk+Path.GetFileName(f)))File.Copy(f,bk+Path.GetFileName(f));if(ShaderUtil.ShaderHasError(p.renderer.sharedMaterial.shader))throw new Exception("Ground shader errors");var rs=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).ToArray();var fountain=rs.First(r=>r.name=="Fountain_polySurface47 (1)");var trees=rs.Where(r=>r.name.StartsWith("Grass path")&&Mathf.Abs(r.bounds.center.x-p.rect.x)<p.rect.z-2&&Mathf.Abs(r.bounds.center.z-p.rect.y)<p.rect.w-2).OrderBy(r=>r.bounds.center.z).ToArray();File.WriteAllLines("FinalEnvironmentRoadReview/CasinoPavingTrees.txt",rs.Where(r=>Mathf.Abs(r.bounds.center.x-p.rect.x)<p.rect.z&&Mathf.Abs(r.bounds.center.z-p.rect.y)<p.rect.w&&r.bounds.min.y<30).Select(r=>r.name+" "+r.bounds));if(trees.Length<2||trees.Length>12)throw new Exception("Unexpected existing tree beds: "+trees.Length);p.data.x=5;p.data.z=trees.Length;p.feature0=new Vector4(fountain.bounds.center.x,fountain.bounds.center.z,0,0);p.feature1=new Vector4(-397,0,0,0);for(int i=0;i<trees.Length;i++){var c=trees[i].bounds.center;p.patches[i]=new Vector4(c.x,c.z,2.4f,3.2f);p.modes[i]=new Vector4(3,0,1,0);}map.Apply();EditorUtility.SetDirty(map);PrefabUtility.RecordPrefabInstancePropertyModifications(map);PrefabUtility.ApplyObjectOverride(map,prefab,InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);var ctrl=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=ctrl.IsNight;try{ctrl.ApplyDay();map.Apply();var cap=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.NonPublic|BindingFlags.Static);cap.Invoke(null,new object[]{sc,new Vector3(-300,60,-495.96f),new Vector3(-390,36,-495.96f),"Casino-Paving-Approved-Front"});cap.Invoke(null,new object[]{sc,new Vector3(-401,150,-495.96f),new Vector3(-401,27.74f,-495.96f),"Casino-Paving-Full-Plot-Top"});cap.Invoke(null,new object[]{sc,new Vector3(-493,60,-495.70f),new Vector3(-423,33,-495.70f),"Casino-Paving-Rear"});cap.Invoke(null,new object[]{sc,new Vector3(-405,63,-578),new Vector3(-409,29,-518),"Casino-Paving-Side"});}finally{if(night)ctrl.ApplyNight();else ctrl.ApplyDay();map.Apply();}EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/CasinoPavingLayout.txt","SUCCESS polySurface285 casino paving: existing fountain-centered stone rings, charcoal approach, muted brass inlays, full front, rear and side paving with grass texture patches centered on all existing tree beds. Existing material and texture atlas reused; zero new material/texture/mesh assets, no UV changes, no props moved. Scene and source prefab saved. Trees="+string.Join(";",trees.Select(t=>t.bounds.center.ToString()))+"; fountain="+fountain.bounds.center+"; shader errors=False.");File.WriteAllText("CityGroundTextureVerify.request","run");}}